import React, { useState, useEffect } from 'react';
import './App.css';
import { 
  ResponsiveContainer, 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  Tooltip 
} from 'recharts';
import { 
  Wallet, 
  ArrowUpCircle, 
  ArrowDownCircle, 
  PlusCircle, 
  History, 
  LayoutDashboard 
} from 'lucide-react';

const API_URL = 'http://localhost:5138/api/transactions';

export default function App() {
  const [transactions, setTransactions] = useState([]);
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState('Ingreso');
  const [loading, setLoading] = useState(false);

  const fetchTransactions = async () => {
    try {
      const res = await fetch(API_URL);
      if (res.ok) {
        const data = await res.json();
        setTransactions(data);
      }
    } catch (error) {
      console.error("Error conectando con la API:", error);
    }
  };

  useEffect(() => {
    fetchTransactions();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!description || !amount) return;

    const newTransaction = {
      description,
      amount: parseFloat(amount),
      type,
      date: new Date().toISOString()
    };

    try {
      setLoading(true);
      const res = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newTransaction)
      });

      if (res.ok) {
        setDescription('');
        setAmount('');
        fetchTransactions();
      }
    } catch (error) {
      console.error("Error al guardar:", error);
    } finally {
      setLoading(false);
    }
  };

  const ingresos = transactions
    .filter(t => t.type === 'Ingreso')
    .reduce((sum, t) => sum + t.amount, 0);

  const gastos = transactions
    .filter(t => t.type === 'Gasto')
    .reduce((sum, t) => sum + t.amount, 0);

  const balanceTotal = ingresos - gastos;

  const chartData = transactions.slice().reverse().map(t => ({
    name: t.description,
    Monto: t.amount,
    tipo: t.type
  }));

  return (
    <div className="app-container">
      <aside className="sidebar">
        <h2>Finanzas Pro</h2>
        <div className="menu-item active">
          <LayoutDashboard size={20} />
          <span>Dashboard</span>
        </div>
        <div className="menu-item">
          <History size={20} />
          <span>Historial</span>
        </div>
      </aside>

      <main className="main-content">
        <section className="metrics-grid">
          <div className="metric-card">
            <div className="metric-info">
              <span>Ingresos</span>
              <h3 style={{ color: '#10b981' }}>\${ingresos.toFixed(2)}</h3>
            </div>
            <ArrowUpCircle color="#10b981" size={40} />
          </div>

          <div className="metric-card">
            <div className="metric-info">
              <span>Gastos</span>
              <h3 style={{ color: '#ef4444' }}>\${gastos.toFixed(2)}</h3>
            </div>
            <ArrowDownCircle color="#ef4444" size={40} />
          </div>

          <div className="metric-card">
            <div className="metric-info">
              <span>Balance Total</span>
              <h3>\${balanceTotal.toFixed(2)}</h3>
            </div>
            <Wallet color="#2563eb" size={40} />
          </div>
        </section>

        <div className="dashboard-body">
          <div className="card-panel">
            <h3>Evolución Financiera (Últimos Movimientos)</h3>
            {chartData.length === 0 ? (
              <p style={{ color: '#787f99' }}>Agrega movimientos para generar analíticas.</p>
            ) : (
              <div style={{ width: '100%', height: 300 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData}>
                    <XAxis dataKey="name" stroke="#787f99" />
                    <YAxis stroke="#787f99" />
                    <Tooltip contentStyle={{ backgroundColor: '#1a1b26', border: '1px solid #222436' }} />
                    <Area type="monotone" dataKey="Monto" stroke="#2563eb" fill="#2563eb" fillOpacity={0.2} />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            <div className="recent-activity">
              <h3>Transactions / Recent Activity</h3>
              <div className="transaction-list">
                {transactions.slice(0, 4).map((t) => (
                  <div key={t.id} className="transaction-item">
                    <div className="tx-info">
                      <h4>{t.description}</h4>
                      <span>{t.type}</span>
                    </div>
                    <span className={`tx-amount ${t.type.toLowerCase()}`}>
                      {t.type === 'Ingreso' ? '+' : '-'} \${t.amount.toFixed(2)}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="card-panel">
            <h3>
              <PlusCircle size={18} style={{ marginRight: 8, verticalAlign: 'middle' }} />
              Agregar Transacción
            </h3>
            <form onSubmit={handleSubmit}>
              <div className="form-group">
                <label>Descripción</label>
                <input 
                  type="text" 
                  placeholder="Ej. Sueldo, Almuerzo" 
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                />
              </div>

              <div className="form-group">
                <label>Monto</label>
                <input 
                  type="number" 
                  step="0.01"
                  placeholder="Monto" 
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                />
              </div>

              <div className="form-group">
                <label>Tipo de Transacción</label>
                <select value={type} onChange={(e) => setType(e.target.value)}>
                  <option value="Ingreso">Ingreso</option>
                  <option value="Gasto">Gasto</option>
                </select>
              </div>

              <button type="submit" className="btn-submit" disabled={loading}>
                {loading ? 'Guardando...' : 'Guardar'}
              </button>
            </form>
          </div>
        </div>
      </main>
    </div>
  );
}
